(S, "Who is the legendary squash player of Pakistan who won the World Open six times?", ["Imran Khan", "Jahangir Khan", "Hashim Khan only", "Shahid Afridi"], 1, "Jahangir Khan is regarded as the greatest squash player ever and won the World Open six times.", "He was unbeaten in 555 consecutive matches from 1981 to 1986.", [4464]),
(S, "When did World War 1 start?", ["1912", "1914", "1916", "1918"], 1, "World War 1 began in July 1914 after the assassination of Archduke Franz Ferdinand.", "It ended in November 1918.", [586]),
(S, "When did World War 2 start?", ["1937", "1938", "1939", "1941"], 2, "World War 2 began on 1 September 1939 when Germany invaded Poland.", "It ended in 1945 with the surrender of Germany in May and Japan in September.", [28]),
(S, "In which year were the Engineering Research Laboratories (later Khan Research Laboratories) of Dr A. Q. Khan established at Kahuta?", ["1974", "1976", "1981", "1998"], 1, "Dr A. Q. Khan founded the laboratory in 1976 to build uranium enrichment capability.", "It was renamed Khan Research Laboratories in 1981 by President Zia-ul-Haq.", [3578]),
(S, "Who is the head of state of Pakistan according to the 1973 Constitution (currently in office, 2026)?", ["Shehbaz Sharif", "Asif Ali Zardari", "Arif Alvi", "Asim Munir"], 1, "The President is the head of state, and Asif Ali Zardari has held the office since 10 March 2024.", "His predecessor was Arif Alvi (2018 to 2024); the Prime Minister is head of government.", [1512, 763, 4530, 371]),
